package candidate

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"net/http"
	"sort"

	"github.com/XUJiahua/enterprise_agent/internal/app"
	"github.com/XUJiahua/enterprise_agent/internal/protocol"
	"github.com/jackc/pgx/v5/pgxpool"
)

const operation = "bulk-approve.v3"

func New(ctx context.Context, pool *pgxpool.Pool, fallback http.Handler) (http.Handler, error) {
	approve := func(ctx context.Context, u app.Identity, key string, ids []string) (protocol.Result, bool, error) {
		// The adapter canonicalizes the IDs, but keep this copy local so the
		// transaction's request hash and response cannot be changed by a caller.
		ids = append([]string(nil), ids...)
		sort.Strings(ids)
		requestHash := hashRequest(ids)
		result := protocol.Result{ApprovedIDs: ids}
		response, err := json.Marshal(result)
		if err != nil {
			return protocol.Result{}, false, err
		}

		tx, err := pool.Begin(ctx)
		if err != nil {
			return protocol.Result{}, false, err
		}
		defer tx.Rollback(ctx)

		// These settings are transaction-local and are deliberately set from
		// the authenticated identity, never from request-supplied headers.
		_, err = tx.Exec(ctx, `SELECT set_config('app.tenant',$1,true),set_config('app.user',$2,true),set_config('app.role',$3,true)`, u.Tenant, u.User, u.Role)
		if err != nil {
			return protocol.Result{}, false, err
		}

		// Claim the scoped key before touching purchases.  ON CONFLICT waits for
		// a concurrent claimant, making same-key requests converge on one row.
		tag, err := tx.Exec(ctx, `INSERT INTO "ActionRequest" ("tenantId","actorId",operation,key,"requestHash",response)
			VALUES ($1,$2,$3,$4,$5,$6) ON CONFLICT ("tenantId","actorId",operation,key) DO NOTHING`,
			u.Tenant, u.User, operation, key, requestHash, response)
		if err != nil {
			return protocol.Result{}, false, err
		}
		if tag.RowsAffected() == 0 {
			var storedHash string
			var storedResponse []byte
			err = tx.QueryRow(ctx, `SELECT "requestHash",response FROM "ActionRequest"
				WHERE "tenantId"=$1 AND "actorId"=$2 AND operation=$3 AND key=$4`,
				u.Tenant, u.User, operation, key).Scan(&storedHash, &storedResponse)
			if err != nil {
				return protocol.Result{}, false, err
			}
			if storedHash != requestHash {
				return protocol.Result{}, false, &protocol.Rejection{Status: 409}
			}
			var replay protocol.Result
			if err = json.Unmarshal(storedResponse, &replay); err != nil {
				return protocol.Result{}, false, err
			}
			if err = tx.Commit(ctx); err != nil {
				return protocol.Result{}, false, err
			}
			return replay, true, nil
		}

		// Lock one target at a time in canonical order.  This both validates the
		// complete batch before mutation and gives overlapping distinct keys a
		// deterministic lock order, so a losing batch cannot partially commit.
		for _, id := range ids {
			var found string
			err = tx.QueryRow(ctx, `SELECT id FROM "Purchase"
				WHERE id=$1 AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted' FOR UPDATE`,
				id, u.Tenant, u.User).Scan(&found)
			if err != nil {
				return protocol.Result{}, false, &protocol.Rejection{Status: 409}
			}
		}

		for _, id := range ids {
			_, err = tx.Exec(ctx, `UPDATE "Purchase" SET status='approved'
				WHERE id=$1 AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted'`,
				id, u.Tenant, u.User)
			if err != nil {
				return protocol.Result{}, false, err
			}
			_, err = tx.Exec(ctx, `INSERT INTO "ApprovalAudit"
				("tenantId","purchaseId","approvedBy",operation,"idempotencyKey","fromStatus","toStatus")
				VALUES ($1,$2,$3,$4,$5,'submitted','approved')`,
				u.Tenant, id, u.User, operation, key)
			if err != nil {
				return protocol.Result{}, false, err
			}
		}

		if err = tx.Commit(ctx); err != nil {
			return protocol.Result{}, false, err
		}
		return result, false, nil
	}
	return protocol.HTTP(approve, fallback), nil
}

func hashRequest(ids []string) string {
	h := sha256.New()
	_, _ = h.Write([]byte(operation + "\n"))
	for _, id := range ids {
		_, _ = fmt.Fprintf(h, "%d:%s", len([]byte(id)), id)
	}
	return hex.EncodeToString(h.Sum(nil))
}

